pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address recipient, uint88 amount) public {
        address vader = address(new Helper());
        address usdv = address(new Helper());
        address vault = address(new Helper());
        c.init(vader, usdv, vault);

        vm.assume(amount > 0);
        vm.assume(recipient != address(0));

        uint256 preCount = c.proposalCount();
        c.newGrantProposal(recipient, uint256(amount));
        uint256 postCount = c.proposalCount();

        assertTrue(postCount == preCount + 1);

        (address storedRecipient, uint256 storedAmount) = c.mapPID_grant(postCount);
        assertTrue(storedRecipient == recipient && storedAmount == uint256(amount));
    }
}

contract Helper {
    fallback() external payable {}
}
